def action_scene(action, value, b, p):
    """Return fresh, unbound beats; caller supplies actual venue/portrait binding."""
    if action == 'support':
        rows = SUPPORT_SCENES.get(value)
    elif action == 'disclose':
        who, _, topic = value.partition(':')
        if topic == 'account':
            rows = [
                ('elias', 'Until him, I knew how a room would end. Even a hostile one. There was always something I could do with it.'),
                (None, "He keeps the account to the selected listener. Saying it aloud removes a little of the grandeur he has given it in private. He resists the urge to restore that grandeur with a more beautiful sentence."),
                ('elias', 'Now I find myself improving answers to questions he has not asked. I would prefer you not mistake that for an instruction.'),
                (who, {'mavis': 'Then tell me what he did ask. I can work with that.', 'martos': 'Your reason is yours. The commitment you make to us still has to hold.', 'camila': 'Keep the extra preparation separate from the objective. Especially when somebody else is paying for it.'}[who]),
                (None, "The reply does not solve him. It leaves him responsible for the distinction he has just admitted. This colleague has heard the selected private account; no other listener acquires it from the conversation."),
            ]
        else:
            rows = [
                ('elias', 'You have the operational account. I am keeping the rest to myself.'),
                (who, {'mavis': 'Fine. Keep the route changes in the part you do tell me.', 'martos': 'You can keep your reason. Keep the commitment as well.', 'camila': 'Then give me the sources. I do not need a confession to check them.'}[who]),
                (None, "He had almost prepared an explanation for choosing privacy. The listener has accepted the boundary without demanding one. He leaves the personal history unshared and returns to the work they have actually agreed to do."),
            ]
    else:
        rows = ACTION_SCENES.get((action, value))
    return [b(who, text) if who else p(text) for who, text in rows] if rows else None
